class Solution:
    def maxAlternatingSum(self, nums: list[int]) -> int:
        even_sum = 0
        odd_sum = 0
        for x in nums:
            new_even = max(even_sum, odd_sum + x)
            new_odd = max(odd_sum, even_sum - x)
            even_sum, odd_sum = new_even, new_odd
        return even_sum

class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        long long evenSum = 0;
        long long oddSum = 0;
        for (int x : nums) {
            long long newEven = max(evenSum, oddSum + x);
            long long newOdd = max(oddSum, evenSum - x);
            evenSum = newEven;
            oddSum = newOdd;
        }
        return evenSum;
    }
};

class Solution {
    public long maxAlternatingSum(int[] nums) {
        long evenSum = 0;
        long oddSum = 0;
        for (int x : nums) {
            long newEven = Math.max(evenSum, oddSum + x);
            long newOdd = Math.max(oddSum, evenSum - x);
            evenSum = newEven;
            oddSum = newOdd;
        }
        return evenSum;
    }
}

var maxAlternatingSum = function(nums) {
  let evenSum = 0;
  let oddSum = 0;
  for (const x of nums) {
    const newEven = Math.max(evenSum, oddSum + x);
    const newOdd = Math.max(oddSum, evenSum - x);
    evenSum = newEven;
    oddSum = newOdd;
  }
  return evenSum;
};
